// Pixel toys: effects that compute every cell of the picture in JS and hand
// the cells to frameos.pixels, a palette byte each, written straight into the
// panel (no canvas, no SVG, no markup). Each effect is a component: make(cols,
// rows) gives its cells, its palette and a step(), so "all at once" is a grid
// of them, each a layer of the frame, and the controls are one more layer.
// Swipe left or right for the next or previous effect; tap a tile to open it.
import { setSeed } from './random'
import { countFrame, fpsText, labelIn, labelLayer, labelOut, resetCount } from './counter'
import { barHeightFor, barLayer, buttonAt } from './controls'
import { makeFire } from './fire'
import { makeFireworks } from './fireworks'
import { makeFountain } from './fountain'
import { makeWaterfall } from './waterfall'
import { makeStarfield } from './starfield'
import { makeMatrix } from './matrix'
import { makeRipples } from './ripples'
import { makeBlobs } from './blobs'
import { makePlasma } from './plasma'
import { makeLife } from './life'

type Effect = {
  cells: Uint8Array | Uint8ClampedArray
  palette: Uint32Array
  text: number
  box: number
  step(): void
  poke?(x: number, y: number): void
}
// `small` and `large`: the automatic cell size on an ESP32 and elsewhere.
type Kind = { id: string; label: string; make(cols: number, rows: number): Effect; small: number; large: number }

const KINDS: Kind[] = [
  { id: 'fire', label: 'FIRE', make: (c, r) => makeFire(c, r, 'fire'), small: 8, large: 4 },
  { id: 'bluefire', label: 'BLUE FIRE', make: (c, r) => makeFire(c, r, 'blue'), small: 8, large: 4 },
  { id: 'greenfire', label: 'GREENFIRE', make: (c, r) => makeFire(c, r, 'green'), small: 8, large: 4 },
  { id: 'fireworks', label: 'FIREWORKS', make: makeFireworks, small: 4, large: 2 },
  { id: 'fountain', label: 'FOUNTAIN', make: makeFountain, small: 4, large: 2 },
  { id: 'waterfall', label: 'WATERFALL', make: makeWaterfall, small: 4, large: 2 },
  { id: 'starfield', label: 'STARFIELD', make: makeStarfield, small: 4, large: 2 },
  { id: 'matrix', label: 'MATRIX', make: makeMatrix, small: 4, large: 2 },
  { id: 'ripples', label: 'RIPPLES', make: makeRipples, small: 8, large: 4 },
  { id: 'blobs', label: 'BLOBS', make: makeBlobs, small: 8, large: 4 },
  { id: 'plasma', label: 'PLASMA', make: makePlasma, small: 8, large: 4 },
  { id: 'life', label: 'LIFE', make: makeLife, small: 8, large: 4 },
]
const KIND: Record<string, Kind> = {}
for (const kind of KINDS) KIND[kind.id] = kind
const ALL = 'all'
const ORDER = [ALL, ...KINDS.map((kind) => kind.id)]
// The tiles of "all at once", first to last.
const GRID = ['fire', 'fireworks', 'plasma', 'waterfall', 'blobs', 'matrix', 'starfield', 'ripples', 'life',
  'fountain', 'bluefire', 'greenfire']
const SIZES = [2, 4, 8]
const GAP = 4

type Tile = { effect: Effect; id: string; x: number; y: number; cols: number; rows: number; size: number }

// What outlives a render while the interpreter does. An ESP32 short of
// memory drops the interpreter, and the effects start again.
let key = ''
let tiles: Tile[] = []
let embedded: boolean | null = null
let lastSingle = 'fire'

function settings(app: any, width: number, height: number) {
  const config = app.config
  const on = (v: unknown) => v === true || v === 'true'
  const effect = config.effect === ALL || KIND[config.effect] ? config.effect : ALL
  return {
    effect,
    asked: Math.round(Number(config.pixelSize) || 0),
    width,
    height,
    controls: on(config.showControls),
    fps: on(config.showFps),
    seed: Math.round(Number(config.seed) || 0),
  }
}

function cellSize(s: ReturnType<typeof settings>): number {
  if (s.asked >= 1) return Math.min(32, s.asked)
  if (s.effect === ALL) return embedded ? 4 : 2
  return embedded ? KIND[s.effect].small : KIND[s.effect].large
}

/** The tiles for these settings: made again only when they change. */
function arrange(s: ReturnType<typeof settings>, size: number) {
  const area = s.height - (s.controls ? barHeightFor(s.width) : 0)
  const next = [s.effect, size, s.width, area].join(':')
  if (next === key) return
  key = next
  setSeed(s.seed > 0 ? s.seed : Date.now() ^ (Math.random() * 0x7fffffff))
  tiles = []
  if (s.effect !== ALL) {
    const cols = Math.max(1, Math.floor(s.width / size))
    const rows = Math.max(1, Math.floor(area / size))
    tiles.push({ effect: KIND[s.effect].make(cols, rows), id: s.effect, x: 0, y: 0, cols, rows, size })
    return
  }
  // A grid as near square tiles as the frame allows: 3x3 on a square panel,
  // 4x2 on a wide one, 3x4 on a tall one.
  const wide = s.width >= area * 1.5
  const across = wide ? 4 : 3
  const down = wide ? 2 : area >= s.width * 1.3 ? 4 : 3
  const tw = Math.floor((s.width - GAP * (across + 1)) / across)
  const th = Math.floor((area - GAP * (down + 1)) / down)
  const cols = Math.max(4, Math.floor(tw / size))
  const rows = Math.max(4, Math.floor(th / size))
  for (let i = 0; i < across * down && i < GRID.length; i++) {
    tiles.push({
      effect: KIND[GRID[i]].make(cols, rows),
      id: GRID[i],
      x: GAP + (i % across) * (tw + GAP) + ((tw - cols * size) >> 1),
      y: GAP + Math.floor(i / across) * (th + GAP) + ((th - rows * size) >> 1),
      cols,
      rows,
      size,
    })
  }
}

export function get(app, context) {
  labelOut() // the frame before this one has been written
  if (embedded === null) embedded = app.frame.embedded === true
  const s = settings(app, context.imageWidth || app.frame.width, context.imageHeight || app.frame.height)
  const size = cellSize(s)
  arrange(s, size)
  if (s.effect !== ALL) lastSingle = s.effect
  for (const tile of tiles) tile.effect.step()
  if (s.fps) countFrame()
  else resetCount()
  if (tiles.length === 1 && !s.controls) {
    // One effect, the whole frame: one frame of cells, which the panel keeps
    // a copy of so it writes only those that change.
    const { effect, cols, rows } = tiles[0]
    if (s.fps) labelIn(effect.cells, cols, rows, effect.text, effect.box, Math.ceil(4 / size))
    return frameos.pixels(effect.cells, { width: cols, height: rows, pixelSize: size, palette: effect.palette })
  }
  const layers: any[] = tiles.map((tile) => ({
    cells: tile.effect.cells,
    x: tile.x,
    y: tile.y,
    width: tile.cols,
    height: tile.rows,
    pixelSize: tile.size,
    palette: tile.effect.palette,
  }))
  if (s.controls) {
    const name = s.effect === ALL ? 'ALL' : KIND[s.effect].label
    layers.push(barLayer(s.width, s.height, name, size, s.fps ? fpsText() : null, s.effect === ALL))
  } else if (s.fps) {
    layers.push(labelLayer(2, GAP, GAP))
  }
  return frameos.pixels(layers)
}

export function onEvent(app, context) {
  const s = settings(app, app.frame.width, app.frame.height)
  const payload = context.payload || {}
  const at = ORDER.indexOf(s.effect)
  const go = (step: number) => frameos.setState('effect', ORDER[(at + step + ORDER.length) % ORDER.length])
  if (context.event === 'swipe') {
    if (payload.direction === 'left') go(1)
    else if (payload.direction === 'right') go(-1)
    else return false
    return true
  }
  if (context.event !== 'tap') return false
  const size = cellSize(s)
  switch (s.controls ? buttonAt(payload.x, payload.y, s.height) : null) {
    case 'prev':
      go(-1)
      return true
    case 'next':
      go(1)
      return true
    case 'finer':
      frameos.setState('quality', String(SIZES[Math.max(0, SIZES.indexOf(size) - 1)] ?? 2))
      return true
    case 'coarser':
      frameos.setState('quality', String(SIZES[Math.min(SIZES.length - 1, SIZES.indexOf(size) + 1)] ?? 8))
      return true
    case 'fps':
      frameos.setState('showFps', !s.fps)
      return true
    case 'all':
      frameos.setState('effect', s.effect === ALL ? lastSingle : ALL)
      return true
  }
  // A tile opens its effect; a tap on ripples drops a stone there.
  for (const tile of tiles) {
    const px = (payload.x - tile.x) / tile.size
    const py = (payload.y - tile.y) / tile.size
    if (px < 0 || py < 0 || px >= tile.cols || py >= tile.rows) continue
    if (tiles.length > 1) {
      frameos.setState('effect', tile.id)
      return true
    }
    if (tile.effect.poke) {
      tile.effect.poke(px, py)
      return true
    }
  }
  return false
}

