// Palettes, built once when an effect starts, as Uint32Arrays of 0xRRGGBB:
// the runtime reads one in place, so handing it over every frame is free.

export function rgb(r: number, g: number, b: number): number {
  const c = (v: number) => Math.max(0, Math.min(255, Math.round(v)))
  return (c(r) << 16) | (c(g) << 8) | c(b)
}

/** A hue (0..1), saturation and value (0..1) as 0xRRGGBB. */
export function hsv(h: number, s: number, v: number): number {
  const i = Math.floor(h * 6)
  const f = h * 6 - i
  const p = v * (1 - s)
  const q = v * (1 - f * s)
  const t = v * (1 - (1 - f) * s)
  const k = ((i % 6) + 6) % 6
  const [r, g, b] = [[v, t, p], [q, v, p], [p, v, t], [p, q, v], [t, p, v], [v, p, q]][k]
  return rgb(r * 255, g * 255, b * 255)
}

/** Stops [at (0..1), 0xRRGGBB] blended into `count` colors. */
export function gradient(count: number, stops: [number, number][]): Uint32Array {
  const out = new Uint32Array(count)
  for (let i = 0; i < count; i++) {
    const at = count === 1 ? 0 : i / (count - 1)
    let k = 0
    while (k < stops.length - 2 && at > stops[k + 1][0]) k++
    const [a0, c0] = stops[k]
    const [a1, c1] = stops[k + 1]
    const f = a1 === a0 ? 0 : Math.max(0, Math.min(1, (at - a0) / (a1 - a0)))
    const mix = (shift: number) => ((c0 >> shift) & 255) * (1 - f) + ((c1 >> shift) & 255) * f
    out[i] = rgb(mix(16), mix(8), mix(0))
  }
  return out
}

/** The palette index whose color is brightest (or darkest). */
export function brightest(palette: Uint32Array, darkest = false): number {
  const luma = (c: number) => ((c >> 16) & 255) * 77 + ((c >> 8) & 255) * 150 + (c & 255) * 29
  let best = 0
  for (let i = 1; i < palette.length; i++) {
    if (darkest ? luma(palette[i]) < luma(palette[best]) : luma(palette[i]) > luma(palette[best])) best = i
  }
  return best
}

