// A 3x5 font, 15 bits a glyph, top row first: the FPS counter, the controls
// and the Matrix rain are drawn with it, a cell a dot.
export const GLYPHS: Record<string, number> = {
  A: 0x2bed, B: 0x6bae, C: 0x3923, D: 0x6b6e, E: 0x79a7, F: 0x79a4, G: 0x396b, H: 0x5bed, I: 0x7497,
  J: 0x126a, K: 0x5bad, L: 0x4927, M: 0x5fed, N: 0x6b6d, O: 0x2b6a, P: 0x6ba4, Q: 0x2b73, R: 0x6bad,
  S: 0x388e, T: 0x7492, U: 0x5b6f, V: 0x5b6a, W: 0x5bfd, X: 0x5aad, Y: 0x5a92, Z: 0x72a7,
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, '+': 0x05d0, '<': 0x1511, '>': 0x4454, '.': 0x0002, ':': 0x0410, '/': 0x12a4, ' ': 0,
}
export const GLYPH_LIST = Object.values(GLYPHS).filter((g) => g !== 0)

/** Cells `text` takes at `scale`: 4 a letter (3 and a gap), less the last gap. */
export function textWidth(text: string, scale: number): number {
  return Math.max(0, text.length * 4 - 1) * scale
}

/** One glyph's dots into `cells` (a grid `cols` wide) at (x, y), `value` each. */
export function drawGlyph(cells: any, cols: number, rows: number, bits: number, x: number, y: number,
    scale: number, value: number) {
  for (let i = 0; i < 15; i++) {
    if (!(bits & (1 << (14 - i)))) continue
    const left = x + (i % 3) * scale
    const top = y + ((i / 3) | 0) * scale
    for (let dy = 0; dy < scale; dy++) {
      const yy = top + dy
      if (yy < 0 || yy >= rows) continue
      for (let dx = 0; dx < scale; dx++) {
        const xx = left + dx
        if (xx >= 0 && xx < cols) cells[yy * cols + xx] = value
      }
    }
  }
}

export function drawText(cells: any, cols: number, rows: number, text: string, x: number, y: number,
    scale: number, value: number) {
  for (let g = 0; g < text.length; g++) {
    drawGlyph(cells, cols, rows, GLYPHS[text[g]] ?? 0, x + g * 4 * scale, y, scale, value)
  }
}

sources.counter.ts:
// The FPS counter: the renders a second the panel really gets (simulation,
// blit and pacing included). Drawn into an effect's own cells for the blit
// and taken out again before its next step, so it neither slows what it
// measures nor feeds the effect; or, over tiles and controls, as a label.
import { GLYPHS, drawText, textWidth } from './font'

let fps: number | null = null
let frames = 0
let windowStart = 0

/** One more render; the rate over the last second, or null for a while. */
export function countFrame(): number | null {
  const now = Date.now()
  if (!windowStart) windowStart = now
  frames++
  const elapsed = now - windowStart
  if (elapsed >= 1000) {
    fps = Math.round((frames * 1000) / elapsed)
    frames = 0
    windowStart = now
  }
  return fps
}

export function resetCount() {
  frames = 0
  windowStart = 0
}

export function fpsText(): string {
  return (fps === null ? '--' : fps) + ' FPS'
}

// In an effect's cells: what the label covered, put back before the next step.
let under: Uint8Array | null = null
let held: any = null
let heldCols = 0
let heldScale = 0
let heldWidth = 0
let heldHeight = 0

export function labelOut() {
  if (!held || !under) return
  for (let y = 0; y < heldHeight; y++) {
    held.set(under.subarray(y * heldWidth, (y + 1) * heldWidth), (y + heldScale) * heldCols + heldScale)
  }
  held = null
}

export function labelIn(cells: any, cols: number, rows: number, text: number, box: number, scale: number) {
  const value = fpsText()
  const width = textWidth(value, scale) + 2 * scale
  const height = 7 * scale
  if (width + scale > cols || height + scale > rows) return
  if (!under || under.length < width * height) under = new Uint8Array(width * height)
  for (let y = 0; y < height; y++) {
    const at = (y + scale) * cols + scale
    under.set(cells.subarray(at, at + width), y * width)
    cells.fill(box, at, at + width)
  }
  drawText(cells, cols, rows, value, 2 * scale, 2 * scale, scale, text)
  held = cells
  heldCols = cols
  heldScale = scale
  heldWidth = width
  heldHeight = height
}

/** The label as a layer of its own: white on black. */
export function labelLayer(scale: number, x: number, y: number) {
  const value = fpsText()
  const cols = textWidth(value, scale) + 2 * scale
  const rows = 7 * scale
  const cells = new Uint8Array(cols * rows)
  drawText(cells, cols, rows, value, scale, scale, scale, 1)
  return { cells, x, y, width: cols, height: rows, palette: LABEL_PALETTE }
}

const LABEL_PALETTE = new Uint32Array([0x000000, 0xffffff])
export { GLYPHS }

