// The controls: a bar along the bottom with buttons, drawn in cells with the
// 3x5 font, a layer of its own over the effect. A tap is looked up in the
// buttons it last drew.
import { drawText, textWidth } from './font'

const PALETTE = new Uint32Array([0x0b0e13, 0x262d38, 0xffffff, 0x8f9bad, 0x2f7de1])
const BG = 0
const BUTTON = 1
const TEXT = 2
const DIM = 3
const ON = 4

type Button = { id: string; x0: number; x1: number }

let cells: Uint8Array | null = null
let drawnKey = ''
let buttons: Button[] = []
let barHeight = 0

/** The bar's height in pixels for a frame `width` wide. */
export function barHeightFor(width: number): number {
  return 5 * (width >= 400 ? 3 : 2) + 12
}

/** The bar for a frame `width` x `height`: the effect's name, its cell size,
 *  the frame rate when counted, and whether all effects show. */
export function barLayer(width: number, height: number, name: string, size: number, fps: string | null, all: boolean) {
  const scale = width >= 400 ? 3 : 2
  const rows = barHeightFor(width)
  const key = [width, name, size, fps, all].join('|')
  if (!cells || cells.length !== width * rows) cells = new Uint8Array(width * rows)
  if (key !== drawnKey) {
    drawnKey = key
    barHeight = rows
    const c = cells
    c.fill(BG)
    buttons = []
    const top = 6
    const pad = 3 * scale
    let x = 4
    const button = (id: string, label: string, on = false, minWidth = 0) => {
      const w = Math.max(minWidth, textWidth(label, scale) + 2 * pad)
      if (x + w > width) return
      for (let y = 3; y < rows - 3; y++) c.fill(on ? ON : BUTTON, y * width + x, y * width + x + w)
      drawText(c, width, rows, label, x + ((w - textWidth(label, scale)) >> 1), top, scale, TEXT)
      buttons.push({ id, x0: x, x1: x + w })
      x += w + 4
    }
    const text = (label: string, value: number, room: number) => {
      drawText(c, width, rows, label, x + ((room - textWidth(label, scale)) >> 1), top, scale, value)
      x += room + 4
    }
    button('prev', '<')
    text(name, TEXT, textWidth('WATERFALL', scale))
    button('next', '>')
    x += 6
    button('finer', '-')
    text(size + 'PX', DIM, textWidth('8PX', scale))
    button('coarser', '+')
    x += 6
    button('fps', fps === null ? 'FPS' : fps.replace(' FPS', ''), fps !== null, textWidth('FPS', scale) + 2 * pad)
    button('all', 'ALL', all)
  }
  return { cells, x: 0, y: height - rows, width, height: rows, pixelSize: 1, palette: PALETTE }
}

/** The button under a tap at (x, y) in the frame's pixels, if any. */
export function buttonAt(x: number, y: number, height: number): string | null {
  if (!barHeight || y < height - barHeight) return null
  for (const b of buttons) if (x >= b.x0 && x < b.x1) return b.id
  return null
}

sources.trails.ts:
// Glowing dots that fade: palettes of 32 levels a hue (index = hue * 32 +
// level, level 0 black), and a pass that dims what was drawn through a table.
// The pass is the cost of these effects in an interpreter, so it reads only
// the span of each row something was drawn in during the last 32 frames, and
// half the rows each frame (every other one, two steps at a time).
import { hsv } from './colors'

export const LEVELS = 32
export const HUES = 8

/** Eight hues of 32 levels, the brightest whitening as a spark's core does. */
export function rainbowTrails(): Uint32Array {
  const out = new Uint32Array(HUES * LEVELS)
  for (let hue = 0; hue < HUES; hue++) {
    for (let level = 1; level < LEVELS; level++) {
      const v = Math.pow(level / (LEVELS - 1), 1.6)
      const s = level > LEVELS - 6 ? 0.85 - (level - (LEVELS - 6)) * 0.15 : 0.85
      out[hue * LEVELS + level] = hsv(hue / HUES, s, v)
    }
  }
  return out
}

export class Trails {
  cols: number
  rows: number
  fade: Uint8Array
  /** Frames a row stays worth dimming after something was drawn in it. */
  live: Uint8Array
  /** The span of each row drawn in since it last went dark. */
  lo: Int16Array
  hi: Int16Array
  frame = 0

  constructor(cols: number, rows: number, step: number) {
    this.cols = cols
    this.rows = rows
    this.fade = new Uint8Array(256)
    for (let i = 0; i < 256; i++) {
      const level = i & (LEVELS - 1)
      this.fade[i] = level > 2 * step ? i - 2 * step : 0
    }
    this.live = new Uint8Array(rows)
    this.lo = new Int16Array(rows).fill(cols)
    this.hi = new Int16Array(rows).fill(-1)
  }

  /** A dot at cell (x, y) of `value` (hue * 32 + level); nothing off the grid.
   *  Hot loops write the same inline (a call costs as much again). */
  plot(cells: Uint8ClampedArray, x: number, y: number, value: number) {
    x |= 0
    y |= 0
    if (x < 0 || y < 0 || x >= this.cols || y >= this.rows) return
    const at = y * this.cols + x
    if ((cells[at] & (LEVELS - 1)) < (value & (LEVELS - 1))) cells[at] = value
    this.live[y] = LEVELS
    if (x < this.lo[y]) this.lo[y] = x
    if (x > this.hi[y]) this.hi[y] = x
  }

  /** Half the rows one double step darker, in the span they were drawn in. */
  dim(cells: Uint8ClampedArray) {
    const F = this.fade
    const live = this.live
    const lo = this.lo
    const hi = this.hi
    const w = this.cols
    for (let y = this.frame++ & 1; y < this.rows; y += 2) {
      const left = live[y]
      if (left === 0) continue
      const row = y * w
      for (let i = row + lo[y], end = row + hi[y]; i <= end; i++) cells[i] = F[cells[i]]
      if (left > 2) {
        live[y] = left - 2
      } else {
        live[y] = 0
        lo[y] = w
        hi[y] = -1
      }
    }
  }
}

sources.fire.ts:
// Fire: the PlayStation Doom fire, a byte of heat per cell (the Hellfire
// sample's spread, docs/realtime-rendering.md). Heat climbs a row a step from
// the burning bottom row, drifting with the wind and cooling as it goes; the
// cooling follows the grid so the flames stand ~40% of the way up at any cell
// size. One flat branchless pass from the first warm row, its random numbers
// from a table read at a new offset each step.
import { nextInt } from './random'

const DOOM = [
  0x070707, 0x1f0707, 0x2f0f07, 0x470f07, 0x571707, 0x671f07, 0x771f07, 0x8f2707, 0x9f2f07, 0xaf3f07,
  0xbf4707, 0xc74707, 0xdf4f07, 0xdf5707, 0xdf5707, 0xd75f07, 0xd75f07, 0xd7670f, 0xcf6f0f, 0xcf770f,
  0xcf7f0f, 0xcf8717, 0xc78717, 0xc78f17, 0xc7971f, 0xbf9f1f, 0xbf9f1f, 0xbfa727, 0xbfa727, 0xbfaf2f,
  0xb7af2f, 0xb7b72f, 0xb7b737, 0xcfcf6f, 0xdfdf9f, 0xefefc7, 0xffffff,
]
const PALETTES: Record<string, Uint32Array> = {
  fire: Uint32Array.from(DOOM),
  blue: Uint32Array.from(DOOM, (c) => ((c & 0xff) << 16) | (c & 0xff00) | (c >> 16)),
  green: Uint32Array.from(DOOM, (c) => (((c >> 8) & 0xff) << 16) | (((c >> 16) & 0xff) << 8) | (c & 0xff)),
}
const HOT = DOOM.length - 1
const SPREAD = 4096
const WIND = 1

export function makeFire(cols: number, rows: number, kind: string) {
  const heat = new Uint8ClampedArray(cols * rows)
  heat.fill(HOT, (rows - 1) * cols) // the bottom row burns
  // Each cell's chance: the drift (0..3) in the low two bits, the cooling
  // (0..2) above them, so heat falls `cool` a row on average.
  const cool = Math.max(0.25, Math.min(2, HOT / (0.4 * rows)))
  const extra = Math.floor(cool)
  const chance = Math.round((cool - extra) * 256)
  const R = new Uint8Array(cols * rows + SPREAD)
  for (let i = 0; i < R.length; i++) {
    const s = nextInt()
    R[i] = (s & 3) | (Math.min(2, extra + (((s >>> 8) & 255) < chance ? 1 : 0)) << 2)
  }
  let top = rows - 1

  function spread() {
    const h = heat
    const up = WIND - cols
    const off = nextInt() & (SPREAD - 1)
    const n = h.length
    let i = top * cols
    const end = n - ((n - i) & 1)
    for (; i < end; i += 2) {
      let r = R[i + off]
      h[i - (r & 3) + up] = h[i] - (r >> 2)
      r = R[i + 1 + off]
      h[i + 1 - (r & 3) + up] = h[i + 1] - (r >> 2)
    }
    if (i < n) {
      const r = R[i + off]
      h[i - (r & 3) + up] = h[i] - (r >> 2)
    }
    // The next pass starts at the first warm cell this one could reach, or a
    // row lower when the first row it ran is cold.
    const from = top > 1 ? (top - 1) * cols - 6 : 0
    let warm = -1
    for (let j = from; j < top * cols; j++) {
      if (h[j] !== 0) {
        warm = j
        break
      }
    }
    if (warm >= 0) {
      top = Math.max(1, (warm / cols) | 0)
    } else if (top < rows - 1) {
      let cold = true
      for (let j = top * cols, e = j + cols; j < e; j++) {
        if (h[j] !== 0) {
          cold = false
          break
        }
      }
      if (cold) top++
    }
  }

  // Warm up: heat climbs a row a step, so the first frame is a fire.
  for (let i = Math.ceil(rows * 0.6); i > 0; i--) spread()
  return { cells: heat, palette: PALETTES[kind] ?? PALETTES.fire, text: HOT, box: 0, step: spread }
}

