// Fireworks: rockets climb from the bottom, burst at the top of their arc into
// a ring of sparks of one hue, and the sparks slow, sink and fade, each drawing
// the stretch it moved along this frame, so its trail is a line.
import { between, random } from './random'
import { Particles } from './particles'
import { LEVELS, HUES, Trails, rainbowTrails } from './trails'

const ROCKET = 1
const PALETTE = rainbowTrails()

export function makeFireworks(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  const P = new Particles(900)
  const trails = new Trails(cols, rows, 2)
  const g = rows * 0.0016

  function launch() {
    const climb = between(rows * 0.45, rows * 0.8)
    P.add(between(cols * 0.15, cols * 0.85), rows - 1, between(-0.0015, 0.0015) * cols, -Math.sqrt(2 * g * climb),
      1, (random() * HUES) | 0, ROCKET)
  }

  function burst(x: number, y: number, hue: number) {
    const n = 30 + ((random() * 40) | 0)
    const speed = rows * between(0.018, 0.028)
    const second = (hue + 1 + ((random() * (HUES - 1)) | 0)) % HUES
    for (let k = 0; k < n; k++) {
      const a = (k / n) * Math.PI * 2 + random() * 0.2
      const v = speed * between(0.6, 1)
      P.add(x, y, Math.cos(a) * v, Math.sin(a) * v, between(22, 40), random() < 0.2 ? second : hue)
    }
  }

  function step() {
    trails.dim(cells)
    if (random() < 0.045 || P.count === 0) launch()
    const X = P.x
    const Y = P.y
    const VX = P.vx
    const VY = P.vy
    const LIFE = P.life
    const HUE = P.hue
    const live = trails.live
    const lo = trails.lo
    const hi = trails.hi
    const w = cols
    for (let i = P.count - 1; i >= 0; i--) {
      const x0 = X[i]
      const y0 = Y[i]
      let vx = VX[i]
      let vy = VY[i]
      if (P.kind[i] === ROCKET) {
        vy += g
        if (vy >= 0) {
          burst(x0, y0, HUE[i])
          P.remove(i)
          continue
        }
        trails.plot(cells, x0, y0, LEVELS + 18 + ((random() * 10) | 0))
        X[i] = x0 + vx
        Y[i] = y0 + vy
        VY[i] = vy
        continue
      }
      const life = LIFE[i] - 1
      if (life <= 0 || y0 >= rows) {
        P.remove(i)
        continue
      }
      // A spark slows in the air and sinks slowly, as a burst does.
      vx *= 0.95
      vy = vy * 0.95 + g * 0.3
      const x1 = x0 + vx
      const y1 = y0 + vy
      X[i] = x1
      Y[i] = y1
      VX[i] = vx
      VY[i] = vy
      LIFE[i] = life
      const level = life > 10 ? LEVELS - 1 : life < 5 && random() < 0.4 ? 6 : 20 + life
      const value = HUE[i] * LEVELS + level
      const dx = x1 - x0
      const dy = y1 - y0
      const adx = dx < 0 ? -dx : dx
      const ady = dy < 0 ? -dy : dy
      const n = ((adx > ady ? adx : ady) + 1) | 0
      for (let s = 0; s < n; s++) {
        const px = (x0 + (dx * s) / n) | 0
        const py = (y0 + (dy * s) / n) | 0
        if (px < 0 || py < 0 || px >= w || py >= rows) continue
        const at = py * w + px
        if ((cells[at] & (LEVELS - 1)) < level) cells[at] = value
        live[py] = LEVELS
        if (px < lo[py]) lo[py] = px
        if (px > hi[py]) hi[py] = px
      }
    }
  }

  for (let i = 0; i < 3; i++) launch()
  return { cells, palette: PALETTE, text: 7 * LEVELS + LEVELS - 1, box: 0, step }
}

