// A fountain: droplets thrown up from the bottom, falling back and bouncing
// off the floor, the color drifting through the rainbow as the jet sways.
import { between, random } from './random'
import { Particles } from './particles'
import { LEVELS, HUES, Trails, rainbowTrails } from './trails'

const PALETTE = rainbowTrails()

export function makeFountain(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  const P = new Particles(600)
  const trails = new Trails(cols, rows, 3)
  const g = rows * 0.0012
  const up = Math.sqrt(2 * g * rows * 0.75)
  let frame = 0

  function step() {
    trails.dim(cells)
    frame++
    const sway = Math.sin(frame * 0.02) * 0.35
    const hue = ((frame / 90) | 0) % HUES
    for (let k = 0; k < 5; k++) {
      P.add(cols / 2 + between(-0.5, 0.5), rows - 1, (sway + between(-0.25, 0.25)) * up * 0.35,
        -up * between(0.85, 1), between(150, 260), random() < 0.1 ? (hue + 1) % HUES : hue)
    }
    const X = P.x
    const Y = P.y
    const VX = P.vx
    const VY = P.vy
    const LIFE = P.life
    const HUE = P.hue
    const live = trails.live
    const lo = trails.lo
    const hi = trails.hi
    const w = cols
    const floor = rows - 1
    const settle = -g * 4
    for (let i = P.count - 1; i >= 0; i--) {
      let vx = VX[i]
      let vy = VY[i] + g
      const x = X[i] + vx
      let y = Y[i] + vy
      const life = LIFE[i] - 1
      if (life <= 0 || x < 0 || x >= w) {
        P.remove(i)
        continue
      }
      if (y >= floor) {
        // A bounce loses most of the fall; a slow drop settles and goes.
        y = floor
        vy = -vy * 0.45
        vx *= 0.8
        if (vy > settle) {
          P.remove(i)
          continue
        }
      }
      X[i] = x
      Y[i] = y
      VX[i] = vx
      VY[i] = vy
      LIFE[i] = life
      const px = x | 0
      const py = y | 0
      if (py < 0) continue
      const level = vy < 0 ? LEVELS - 1 : LEVELS - 4
      const at = py * w + px
      if ((cells[at] & (LEVELS - 1)) < level) cells[at] = HUE[i] * LEVELS + level
      live[py] = LEVELS
      if (px < lo[py]) lo[py] = px
      if (px > hi[py]) hi[py] = px
    }
  }

  return { cells, palette: PALETTE, text: 7 * LEVELS + LEVELS - 1, box: 0, step }
}

