// A waterfall: water pours over a ledge across the top, streaks down, and
// throws up spray where it meets the pool, which shimmers below. Particles
// with fading trails, in blues that whiten as the water breaks.
import { between, random } from './random'
import { Particles } from './particles'
import { gradient } from './colors'
import { LEVELS, Trails } from './trails'

const PALETTE = gradient(LEVELS, [[0, 0x000000], [0.3, 0x08214a], [0.65, 0x2a7fd4], [0.88, 0x9fe3ff], [1, 0xffffff]])
const POOL = 0.84 // of the height: the water line
const SPRAY = 1

export function makeWaterfall(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  const P = new Particles(900)
  const trails = new Trails(cols, rows, 3)
  const g = rows * 0.0011
  const pool = Math.floor(rows * POOL)
  const left = cols * 0.18
  const right = cols * 0.82

  function step() {
    trails.dim(cells)
    // Over the ledge: a curtain across the top, pushed out a little.
    for (let k = 0; k < 7; k++) {
      P.add(between(left, right), 0, between(-0.05, 0.05), between(0.1, 0.4), 400, 0)
    }
    const X = P.x
    const Y = P.y
    const VX = P.vx
    const VY = P.vy
    const LIFE = P.life
    const KIND = P.kind
    const live = trails.live
    const lo = trails.lo
    const hi = trails.hi
    const w = cols
    for (let i = P.count - 1; i >= 0; i--) {
      let vy = VY[i] + (KIND[i] === SPRAY ? g * 0.6 : g)
      const vx = VX[i]
      const x = X[i] + vx
      const y = Y[i] + vy
      const life = LIFE[i] - 1
      if (life <= 0 || x < 0 || x >= w || y >= rows) {
        P.remove(i)
        continue
      }
      if (KIND[i] !== SPRAY && y >= pool) {
        // Breaks on the pool: a puff of spray, and the drop is gone.
        if (random() < 0.5) {
          P.add(x, pool - 1, between(-0.6, 0.6), -between(0.3, 1.1) * Math.sqrt(g * rows * 0.05), between(8, 18), 0, SPRAY)
        }
        P.remove(i)
        continue
      }
      X[i] = x
      Y[i] = y
      VY[i] = vy
      LIFE[i] = life
      if (y < 0) continue
      const px = x | 0
      const py = y | 0
      // Falling water deepens as it speeds up; spray is white.
      const level = KIND[i] === SPRAY ? LEVELS - 1 : vy > 1.2 ? LEVELS - 6 : LEVELS - 10
      const at = py * w + px
      if (cells[at] < level) cells[at] = level
      live[py] = LEVELS
      if (px < lo[py]) lo[py] = px
      if (px > hi[py]) hi[py] = px
    }
    // The pool: dark water, a few glints moving on it.
    for (let k = 0; k < 6; k++) {
      const x = (random() * w) | 0
      const y = pool + ((random() * (rows - pool)) | 0)
      trails.plot(cells, x, y, 10 + ((random() * 12) | 0))
    }
  }

  return { cells, palette: PALETTE, text: LEVELS - 1, box: 0, step }
}

