// A starfield: stars come at you out of the middle, brighter and longer as
// they near, each a streak from where it was. What a frame drew is remembered
// and cleared before the next.
import { between } from './random'
import { gradient } from './colors'

const PALETTE = gradient(32, [[0, 0x000000], [0.2, 0x2a3870], [0.6, 0xaabcff], [1, 0xffffff]])
const SPEED = 0.014

export function makeStarfield(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  // A star for every ~55 cells, so a small tile is as busy as the panel.
  const N = Math.max(20, Math.min(400, ((cols * rows) / 55) | 0))
  const X = new Float32Array(N)
  const Y = new Float32Array(N)
  const Z = new Float32Array(N)
  const D = new Int32Array(N * 16)
  let drawn = 0

  function respawn(i: number, far: boolean) {
    X[i] = between(-1, 1)
    Y[i] = between(-1, 1)
    Z[i] = far ? between(0.8, 1) : between(0.05, 1)
  }

  function step() {
    for (let k = 0; k < drawn; k++) cells[D[k]] = 0
    let count = 0
    const w = cols
    const h = rows
    const cx = w / 2
    const cy = h / 2
    const scale = (w < h ? w : h) * 0.5
    for (let i = 0; i < N; i++) {
      const z0 = Z[i]
      const z1 = z0 - SPEED
      if (z1 <= 0.02) {
        respawn(i, true)
        continue
      }
      Z[i] = z1
      const sx = X[i] * scale
      const sy = Y[i] * scale
      const x0 = cx + sx / z0
      const y0 = cy + sy / z0
      const x1 = cx + sx / z1
      const y1 = cy + sy / z1
      if (x1 < 0 || y1 < 0 || x1 >= w || y1 >= h) {
        respawn(i, true)
        continue
      }
      const level = (1 - z1) * 40
      const top = level > 31 ? 31 : level
      const dx = x1 - x0
      const dy = y1 - y0
      const adx = dx < 0 ? -dx : dx
      const ady = dy < 0 ? -dy : dy
      let n = (adx > ady ? adx : ady) | 0
      if (n > 14) n = 14
      for (let s = 0; s <= n; s++) {
        const f = n === 0 ? 1 : s / n
        const px = (x0 + dx * f) | 0
        const py = (y0 + dy * f) | 0
        if (px < 0 || py < 0 || px >= w || py >= h) continue
        const at = py * w + px
        const v = (top * (0.3 + 0.7 * f)) | 0
        if (cells[at] < v) cells[at] = v
        D[count++] = at
      }
    }
    drawn = count
  }

  for (let i = 0; i < N; i++) respawn(i, false)
  return { cells, palette: PALETTE, text: 31, box: 0, step }
}

