// Matrix rain: columns of glyphs falling, the newest white, the rest green and
// fading behind it. A glyph is the 3x5 font in a 4x6 block of cells.
import { between, random } from './random'
import { gradient } from './colors'
import { GLYPH_LIST } from './font'
import { LEVELS, Trails } from './trails'

const PALETTE = gradient(LEVELS, [[0, 0x000000], [0.35, 0x003b12], [0.8, 0x14c443], [0.94, 0x8dff9e], [1, 0xe8ffe8]])

export function makeMatrix(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  const trails = new Trails(cols, rows, 1)
  const columns = Math.max(1, (cols / 4) | 0)
  const lines = Math.max(1, (rows / 6) | 0)
  const head = new Float32Array(columns)
  const speed = new Float32Array(columns)
  const last = new Int16Array(columns).fill(-1)

  function drop(c: number, anywhere: boolean) {
    head[c] = anywhere ? between(-lines, lines) : between(-lines * 0.6, 0)
    speed[c] = between(0.15, 0.55)
  }

  function glyph(c: number, line: number, level: number) {
    const bits = GLYPH_LIST[(random() * GLYPH_LIST.length) | 0]
    const x = c * 4
    const y = line * 6
    for (let i = 0; i < 15; i++) {
      if (!(bits & (1 << (14 - i)))) continue
      trails.plot(cells, x + (i % 3), y + ((i / 3) | 0), level)
    }
  }

  function step() {
    trails.dim(cells)
    for (let c = 0; c < columns; c++) {
      const h = (head[c] += speed[c])
      const line = h | 0
      if (line !== last[c] && line >= 0 && line < lines) {
        // The glyph that was the head greens; a new white one leads.
        if (last[c] >= 0) glyph(c, last[c], LEVELS - 5)
        glyph(c, line, LEVELS - 1)
        last[c] = line
      }
      if (h > lines + 8) {
        drop(c, false)
        last[c] = -1
      }
    }
  }

  for (let c = 0; c < columns; c++) drop(c, true)
  return { cells, palette: PALETTE, text: LEVELS - 1, box: 0, step }
}

