// Ripples: water, the classic two-buffer wave. Each cell becomes the average of
// its neighbours less what it was, and loses a little; rain falls now and
// then, and a tap drops a stone where it lands.
import { random } from './random'
import { gradient } from './colors'

const PALETTE = gradient(256, [
  [0, 0x00040f], [0.35, 0x02254d], [0.5, 0x0a4a80], [0.62, 0x2b85c2], [0.8, 0x9ad8f5], [1, 0xffffff],
])

export function makeRipples(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  let a = new Int16Array(cols * rows)
  let b = new Int16Array(cols * rows)
  let frame = 0

  function poke(x: number, y: number, depth = 900) {
    x |= 0
    y |= 0
    for (let dy = -1; dy <= 1; dy++)
      for (let dx = -1; dx <= 1; dx++) {
        const px = x + dx
        const py = y + dy
        if (px > 0 && py > 0 && px < cols - 1 && py < rows - 1) a[py * cols + px] = depth
      }
  }

  function step() {
    frame++
    if (frame % 9 === 0 || random() < 0.03) poke(random() * cols, random() * rows, 500 + random() * 500)
    const w = cols
    const A = a
    const B = b
    const C = cells
    for (let y = 1; y < rows - 1; y++) {
      for (let i = y * w + 1, end = y * w + w - 1; i < end; i++) {
        let v = ((A[i - 1] + A[i + 1] + A[i - w] + A[i + w]) >> 1) - B[i]
        v -= v >> 5
        B[i] = v
        C[i] = 112 + (v >> 2)
      }
    }
    a = B
    b = A
  }

  cells.fill(112)
  return { cells, palette: PALETTE, text: 255, box: 0, step, poke }
}

