// Blobs: a lava lamp of metaballs. Each blob adds its falloff to the cells
// within its radius (a table by squared distance, so no root or division per
// cell), the cells clamp at 255, and the palette draws the surface where the
// sum crosses the middle: a glow outside, a bright rim, a hot core inside.
import { between } from './random'
import { gradient } from './colors'

const K = 6
const PALETTE = gradient(256, [
  [0, 0x05020f], [0.3, 0x1c0838], [0.46, 0x5a1580], [0.5, 0xffd2ef], [0.53, 0xff3c8c],
  [0.75, 0xff7a2a], [1, 0xffe27a],
])

export function makeBlobs(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  const radius = Math.max(3, Math.min(cols, rows) * 0.2)
  const r2 = Math.ceil(radius * radius)
  const fall = new Uint8Array(r2 + 2) // zeros past the edge, for rounding
  for (let d = 0; d < r2; d++) {
    const t = 1 - d / r2
    fall[d] = Math.min(255, Math.round(512 * t * t))
  }
  const fx = new Float32Array(K)
  const fy = new Float32Array(K)
  const px = new Float32Array(K)
  const py = new Float32Array(K)
  for (let k = 0; k < K; k++) {
    fx[k] = between(0.006, 0.016)
    fy[k] = between(0.006, 0.016)
    px[k] = between(0, Math.PI * 2)
    py[k] = between(0, Math.PI * 2)
  }
  let frame = 0

  function step() {
    frame++
    cells.fill(0)
    const F = fall
    const w = cols
    for (let k = 0; k < K; k++) {
      const bx = w * (0.5 + 0.36 * Math.sin(frame * fx[k] + px[k]))
      const by = rows * (0.5 + 0.36 * Math.sin(frame * fy[k] + py[k]))
      const y0 = Math.max(0, Math.ceil(by - radius))
      const y1 = Math.min(rows - 1, Math.floor(by + radius))
      for (let y = y0; y <= y1; y++) {
        const dy = y - by
        const dy2 = dy * dy
        const span = Math.sqrt(Math.max(0, r2 - dy2))
        const x0 = Math.max(0, Math.ceil(bx - span))
        const x1 = Math.min(w - 1, Math.floor(bx + span))
        let j = y * w + x0
        for (let x = x0; x <= x1; x++, j++) {
          const dx = x - bx
          cells[j] += F[(dy2 + dx * dx) | 0]
        }
      }
    }
  }

  return { cells, palette: PALETTE, text: 255, box: 0, step }
}

