// Plasma: three waves summed per cell, from tables made once a frame (a
// column's part, a row's, a diagonal's), so a cell is two reads and two adds.
// The cells are a Uint8Array, so the sum wraps round the palette by itself.
import { random } from './random'
import { brightest } from './colors'

const SIN = new Uint8Array(256)
for (let i = 0; i < 256; i++) SIN[i] = Math.round(127.5 + 127.5 * Math.sin((i / 256) * Math.PI * 2))
const PALETTE = new Uint32Array(256)
for (let i = 0; i < 256; i++) {
  const ch = (d: number) => Math.round(255 * (0.5 + 0.5 * Math.cos(Math.PI * 2 * (i / 256 + d))))
  PALETTE[i] = (ch(0) << 16) | (ch(0.33) << 8) | ch(0.67)
}
const TEXT = brightest(PALETTE)
const BOX = brightest(PALETTE, true)

export function makePlasma(cols: number, rows: number) {
  const cells = new Uint8Array(cols * rows)
  const a = new Uint8Array(cols)
  const b = new Uint8Array(rows)
  const c = new Uint8Array(cols + rows)
  // The waves' lengths follow the grid, so the picture is the same at any
  // cell size; the seed picks their mix.
  const k1 = (256 / cols) * (1 + random())
  const k2 = (256 / rows) * (1 + random())
  const k3 = (128 / (cols + rows)) * (1 + random() * 2)
  let frame = 0

  function step() {
    const t = ++frame
    for (let x = 0; x < cols; x++) a[x] = (SIN[(x * k1 + t * 2) & 255] + SIN[(x * k1 * 0.5 - t) & 255]) >> 2
    for (let y = 0; y < rows; y++) b[y] = (SIN[(y * k2 - t * 3) & 255] + SIN[(y * k2 * 0.7 + t * 2) & 255]) >> 2
    for (let d = 0; d < cols + rows; d++) c[d] = SIN[(d * k3 + t * 4) & 255] >> 1
    const A = a
    const C = c
    const w = cols
    let j = 0
    for (let y = 0; y < rows; y++) {
      const by = b[y] + t
      for (let x = 0; x < w; x++) cells[j++] = A[x] + by + C[x + y]
    }
  }

  return { cells, palette: PALETTE, text: TEXT, box: BOX, step }
}

