// Conway's Life, a cell lit white when it is born and fading through teal
// after it dies. The board is bits, 32 cells to an integer, and a generation
// is a few dozen bitwise operations per 32 cells (the neighbours counted by
// bit-sliced adders), so the cost is drawing the picture, and that only where
// something lived in the last 28 generations. The edges are dead; a board
// that goes quiet gets a few R-pentominoes.
import { random } from './random'
import { gradient } from './colors'

const FADE = 9 // per generation: 255 / 9, 28 generations to black
const PALETTE = gradient(256, [[0, 0x000000], [0.4, 0x061b33], [0.85, 0x139c95], [0.99, 0x63f2c8], [1, 0xf4fff9]])

export function makeLife(cols: number, rows: number) {
  const cells = new Uint8ClampedArray(cols * rows)
  const words = (cols + 31) >> 5
  const S = words + 2 // a zero word at each end of a row
  let now = new Int32Array(S * (rows + 2))
  let next = new Int32Array(S * (rows + 2))
  const lastMask = (cols & 31) === 0 ? -1 : (1 << (cols & 31)) - 1
  const active = new Uint8Array(words * rows)
  let quiet = 0

  function set(x: number, y: number) {
    if (x < 0 || y < 0 || x >= cols || y >= rows) return
    now[(y + 1) * S + 1 + (x >> 5)] |= 1 << (x & 31)
  }

  function sprinkle(count: number) {
    for (let k = 0; k < count; k++) {
      const x = (random() * (cols - 3)) | 0
      const y = (random() * (rows - 3)) | 0
      set(x + 1, y)
      set(x + 2, y)
      set(x, y + 1)
      set(x + 1, y + 1)
      set(x + 1, y + 2)
    }
  }

  function step() {
    const a = now
    const b = next
    let changed = 0
    let alive = 0
    for (let y = 1; y <= rows; y++) {
      const up = (y - 1) * S
      const mid = y * S
      const dn = mid + S
      for (let k = 1; k <= words; k++) {
        const A = a[up + k]
        const B = a[mid + k]
        const C = a[dn + k]
        // The eight neighbours as bitboards, summed into s0, s1 (count mod 4)
        // and s2 (four or more).
        let s0 = (A << 1) | (a[up + k - 1] >>> 31)
        let n = A
        let s1 = s0 & n
        s0 ^= n
        let s2 = 0
        let t = 0
        n = (A >>> 1) | (a[up + k + 1] << 31)
        t = s0 & n; s0 ^= n; s2 |= s1 & t; s1 ^= t
        n = (B << 1) | (a[mid + k - 1] >>> 31)
        t = s0 & n; s0 ^= n; s2 |= s1 & t; s1 ^= t
        n = (B >>> 1) | (a[mid + k + 1] << 31)
        t = s0 & n; s0 ^= n; s2 |= s1 & t; s1 ^= t
        n = (C << 1) | (a[dn + k - 1] >>> 31)
        t = s0 & n; s0 ^= n; s2 |= s1 & t; s1 ^= t
        t = s0 & C; s0 ^= C; s2 |= s1 & t; s1 ^= t
        n = (C >>> 1) | (a[dn + k + 1] << 31)
        t = s0 & n; s0 ^= n; s2 |= s1 & t; s1 ^= t
        // Two neighbours and alive, or three: lives.
        let live = ~s2 & s1 & (s0 | B)
        if (k === words) live &= lastMask
        b[mid + k] = live
        if (live !== B) changed++
        if (live !== 0) alive++
      }
    }
    now = b
    next = a
    const w = cols
    for (let y = 0; y < rows; y++) {
      const row = (y + 1) * S + 1
      for (let k = 0; k < words; k++) {
        let bits = b[row + k]
        const at = y * words + k
        if (bits !== 0) active[at] = 29
        else if (active[at] === 0) continue
        else active[at]--
        let j = y * w + (k << 5)
        const end = k === words - 1 ? y * w + w : j + 32
        for (; j < end; j++, bits >>>= 1) cells[j] = bits & 1 ? 255 : cells[j] - FADE
      }
    }
    quiet = changed <= 2 ? quiet + 1 : 0
    if (quiet > 30 || alive < 2) {
      sprinkle(3)
      quiet = 0
    }
  }

  for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) if (random() < 0.28) set(x, y)
  return { cells, palette: PALETTE, text: 255, box: 0, step }
}
